values
  ('cavoodle', 'Cavoodle', 'common', 1, 'Cavoodles combine the gentle temperament of the Cavalier King Charles Spaniel with the intelligence of the Poodle. They are adaptable family dogs that thrive on companionship and enjoy both playtime and cuddles.', 'Australia', 'Friendly, Intelligent, Affectionate', 'Small', '12–15 years', 'breed-reference/cavoodle.jpg'),
